class Solution {
  public double minPrice(int[] prices, int[] discounts) {
    int[] p = prices.clone(), d = discounts.clone();
    Arrays.sort(p);
    Arrays.sort(d);
    double total = 0;
    for (int x : p) total += x;
    // biggest discount on the biggest price
    for (int i = 0; i < Math.min(p.length, d.length); i++) {
      int price = p[p.length - 1 - i], discount = d[d.length - 1 - i];
      total -= price * discount / 100.0;
    }
    return total;
  }
}
